//! This provides info on codepoints, THE code between START_E_AT and END_E_AT should not be touched an is auto generated by a python script

const std = @import("std");

pub const GraphemeCat = enum { LF, CR, Control, Extend, ZWJ, Regional_Indicator, Prepend, SpacingMark, L, V, T, LV, LVT, E_Base, E_Modifier, Glue_After_Zwj, E_Base_GAZ, Any, Linker, Consonant, None, Extended_Pictographic };
pub const PropertyRange = struct {
    start: u21,
    end: u21,
    property: GraphemeCat,
};

pub const Range = struct {
    start: u21,
    end: u21,
};
pub const WidthSize = enum{
    A,
    F,
    H, 
    N,
    Na,
    W 
};

pub const WidthRange = struct {
    start: u21,
    end: u21,
    width: WidthSize
};

pub fn isMeMn(cp: u21) bool{
    var left: usize = 0;
    var right: usize = cat_ranges.len;

    while (left < right) {
        const mid = left + (right - left) / 2;
        const range = cat_ranges[mid];

        if (cp < range.start) {
            right = mid;
        } else if (cp > range.end) {
            left = mid + 1;
        } else {
            return true;
        }
    }
    return false;
}

pub fn getGraphemeEmoji(cp: u21) bool {
    var left: usize = 0;
    var right: usize = ranges_emoji.len;

    while (left < right) {
        const mid = left + (right - left) / 2;
        const range = ranges_emoji[mid];

        if (cp < range.start) {
            right = mid;
        } else if (cp > range.end) {
            left = mid + 1;
        } else {
            return true;
        }
    }

    return false;
}
pub fn getGraphemeInCB(cp: u21) GraphemeCat {
    var left: usize = 0;
    var right: usize = ranges_incb.len;
    while (left < right) {
        const mid = left + (right - left) / 2;
        const range = ranges_incb[mid];

        if (cp < range.start) {
            right = mid;
        } else if (cp > range.end) {
            left = mid + 1;
        } else {
            return range.property;
        }
    }
    return .None;
}

pub fn getGraphemeCat(cp: u21) GraphemeCat {
    var left: usize = 0;
    var right: usize = ranges.len;

    while (left < right) {
        const mid = left + (right - left) / 2;
        const range = ranges[mid];

        if (cp < range.start) {
            right = mid;
        } else if (cp > range.end) {
            left = mid + 1;
        } else {
            return range.property;
        }
    }

    return .None;
}

pub fn getWidth(cp: u21) ?WidthSize{
    var left: usize = 0;
    var right: usize = width_ranges.len;
    while (left < right) {
        const mid = left + (right - left) / 2;
        const range = width_ranges[mid];
        if (cp < range.start) {
            right = mid;
        } else if (cp > range.end) {
            left = mid + 1;
        } else {
            return range.width;
        }
    }
    return null;
}

