test "Test InCB" {
    try std.testing.expectEqual(GraphemeCat.Linker, getGraphemeInCB(0x094D));
    try std.testing.expectEqual(GraphemeCat.Linker, getGraphemeInCB(0x09CD));
    try std.testing.expectEqual(GraphemeCat.Linker, getGraphemeInCB(0x0ACD));

    try std.testing.expectEqual(GraphemeCat.Consonant, getGraphemeInCB(0x0915));
    try std.testing.expectEqual(GraphemeCat.Consonant, getGraphemeInCB(0x0916));
    try std.testing.expectEqual(GraphemeCat.Consonant, getGraphemeInCB(0x0995));

    try std.testing.expectEqual(GraphemeCat.None, getGraphemeInCB('a'));
    try std.testing.expectEqual(GraphemeCat.None, getGraphemeInCB('A'));
    try std.testing.expectEqual(GraphemeCat.None, getGraphemeInCB(0x093F));
}

test "known properties" {
    try std.testing.expectEqual(GraphemeCat.None, getGraphemeCat(0x0041));
    try std.testing.expectEqual(GraphemeCat.CR, getGraphemeCat(0x000D));
    try std.testing.expectEqual(GraphemeCat.LF, getGraphemeCat(0x000A));
    try std.testing.expectEqual(GraphemeCat.Extend, getGraphemeCat(0x0301));
    try std.testing.expectEqual(GraphemeCat.ZWJ, getGraphemeCat(0x200D));
    try std.testing.expectEqual(
        GraphemeCat.Regional_Indicator,
        getGraphemeCat(0x1F1EF),
    );
}

test "range boundaries" {
    try std.testing.expectEqual(GraphemeCat.Extend, getGraphemeCat(0x0300));
    try std.testing.expectEqual(GraphemeCat.Extend, getGraphemeCat(0x036F));
    try std.testing.expectEqual(GraphemeCat.None, getGraphemeCat(0x02FF));
    try std.testing.expectEqual(GraphemeCat.None, getGraphemeCat(0x0370));
}

test "missing ranges return Any" {
    try std.testing.expectEqual(GraphemeCat.None, getGraphemeCat(0x0041));
    try std.testing.expectEqual(GraphemeCat.None, getGraphemeCat(0x10FFFF));
}
